const body = $json.body ?? $json;
const clean = {
  name: String(body.name ?? '').trim(),
  businessType: String(body.businessType ?? '').trim(),
  monthlyMessages: Number(body.monthlyMessages ?? 0),
  budget: Number(body.budget ?? 0),
  timelineDays: Number(body.timelineDays ?? 30),
  consent: body.consent === true,
};
return [{ json: clean }];

const lead = $json;
let score = 0;
if (lead.consent) score += 25;
if (lead.monthlyMessages >= 300) score += 25;
if (lead.budget >= 100) score += 25;
if (lead.timelineDays <= 30) score += 25;

let status = 'nurture';
if (!lead.consent) status = 'needs-consent';
else if (score >= 75) status = 'qualified';
else if (score >= 50) status = 'review';

return [{
  json: {
    ok: true,
    lead: {
      name: lead.name || 'Anonymous',
      businessType: lead.businessType || 'Not provided'
    },
    score,
    status,
    nextAction: status === 'qualified'
      ? 'Route to a human sales representative.'
      : status === 'needs-consent'
        ? 'Request consent before follow-up.'
        : 'Send an approved informational follow-up.'
  }
}];
